processed_prompts = dict()
prompts = prompts.split(';')
for idx, prompt in enumerate(prompts):
    if len(prompt)<10:
        continue
    quote = '''"'''
    if prompt.startswith(f"{quote}"):
        prompt = prompt[1:]
    if prompt.endswith(f"{quote}"):
        prompt = prompt[:-1]
    if prompt.startswith("\n"):
        prompt = prompt[1:]
    if prompt.endswith("\n"):
        prompt = prompt[:-1]     
    if prompt.startswith("\\"):
        prompt = prompt[1:]
    if prompt.endswith("\\"):
        prompt = prompt[:-1]   
    if prompt.startswith(";"):
        prompt = prompt[1:]
    if prompt.endswith(";"):
        prompt = prompt[:-1]       
    prompt = prompt.strip()
    processed_prompts[idx] = prompt

json_string = json.dumps(processed_prompts, indent=4)
with open("generated_random_prompts.json", "w") as f:
    f.write(json_string)